def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    for _, o in history:
        if o == 'D':
            opp_def += 1

    if n >= 10 and opp_def > n * 0.4:
        return 'D'

    if n >= 2 and history[-1][1] == 'D' and history[-2][1] == 'D':
        return 'D'

    my_last, opp_last = history[-1]
    if my_last == 'C':
        if opp_last == 'C':
            return 'C'
        else:
            return 'D'
    else:
        if opp_last == 'C':
            return 'D'
        else:
            return 'C'
